INSERT INTO public.blitz_questions (topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Конституционный Суд РФ','В проекте штатного состава Конституционного Суда указано 12 судей, включая Председателя и заместителя. Каков установленный законом состав?','["10 судей без учёта Председателя","11 судей, включая Председателя и его заместителя","12 судей, включая Председателя и двух заместителей","15 судей, включая Председателя и его заместителя"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_4172/bc18f52b80604825487100e6aaf18beeb5eb2553/','ФКЗ устанавливает общую численность 11 судей.',true),
('Конституционный Суд РФ','В Конституционном Суде осталось семь действующих судей. Может ли Суд продолжать осуществлять полномочия при таком составе?','["Нет, требуется наличие не менее восьми судей","Да, достаточно семи судей","Да, при согласии Председателя Совета Федерации","Нет, необходимо присутствие всех 11 судей"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_4172/bc18f52b80604825487100e6aaf18beeb5eb2553/','Правомочность Конституционного Суда требует не менее восьми судей в его составе.',true),
('Конституционный Суд РФ','Для Конституционного Суда планируют установить пятилетний срок полномочий самого органа. Какое правило содержит ФКЗ?','["Срок полномочий органа равен шести годам","Срок полномочий органа равен пяти годам","Срок полномочий органа зависит от срока Государственной Думы","Полномочия Конституционного Суда не ограничены определённым сроком"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_4172/bc18f52b80604825487100e6aaf18beeb5eb2553/','Полномочия органа как такового не ограничены сроком.',true),
('Конституционный Суд РФ','Кто назначает судей Конституционного Суда Российской Федерации?','["Президент единолично без участия палаты","Государственная Дума по представлению Правительства","Совет Федерации по представлению Президента РФ","Совет Федерации по представлению Верховного Суда"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_4172/bc18f52b80604825487100e6aaf18beeb5eb2553/','Назначение производится Советом Федерации на основании президентского представления.',true),
('Конституционный Суд РФ','Кандидату в судьи Конституционного Суда 39 лет, а стаж юридической работы составляет 20 лет. Может ли он быть назначен сейчас?','["Да, стаж свыше 15 лет заменяет возрастной ценз","Нет, необходим возраст не менее 40 лет","Да, необходим возраст не менее 35 лет","Нет, необходимо достичь 45 лет"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_4172/ad7bdd8575a7aa72b6e65711392cabc4e2d16831/','Минимальный возраст кандидата в судьи КС РФ — 40 лет.',true),
('Конституционный Суд РФ','Юристу 45 лет, он имеет высшее юридическое образование и 14 лет работы по юридической профессии. Какого условия ему недостаёт?','["Стажа работы по юридической профессии не менее 15 лет","Стажа работы по юридической профессии не менее 20 лет","Возрастного ценза 50 лет","Двух высших юридических образований"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_4172/ad7bdd8575a7aa72b6e65711392cabc4e2d16831/','Минимальный юридический стаж установлен в 15 лет.',true),
('Конституционный Суд РФ','Претенденту в судьи Конституционного Суда 44 года, но у него отсутствует высшее юридическое образование. Какова правовая оценка?','["Требование можно заменить стажем любой работы в 15 лет","Требование касается только судей Верховного Суда","Достаточно среднего специального юридического образования","Не выполнено обязательное квалификационное требование"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_4172/ad7bdd8575a7aa72b6e65711392cabc4e2d16831/','Высшее юридическое образование — обязательное условие назначения.',true),
('Конституционный Суд РФ','Кандидат на должность судьи Конституционного Суда имеет документ, дающий ему право постоянного проживания в иностранном государстве. Может ли он отвечать всем требованиям статьи 8?','["Да, если кандидат не использовал документ последние два года","Да, если документ получен до начала юридической карьеры","Нет, наличие такого документа несовместимо с требованиями","Да, после уведомления Председателя КС РФ"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_4172/ad7bdd8575a7aa72b6e65711392cabc4e2d16831/','Статья 8 исключает иностранное гражданство и документ на постоянное проживание за рубежом.',true),
('Конституционный Суд РФ','Совет Федерации получил представление Президента о назначении судьи Конституционного Суда. В какой срок нужно рассмотреть вопрос?','["Не позднее 7 дней со дня получения представления","Не позднее 14 дней со дня получения представления","Не позднее 30 дней со дня получения представления","Не позднее 60 дней со дня получения представления"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_4172/3e4facc6a5bea986adfaea21324b9fb33929f428/','Предельный срок рассмотрения представления — 14 дней.',true),
('Конституционный Суд РФ','Предлагается утвердить одновременно список из трёх судей Конституционного Суда открытым голосованием. Какова законная процедура?','["Каждого судью назначают индивидуально тайным голосованием","Список утверждают одним открытым голосованием","Список утверждают пофракционным тайным голосованием","Каждого назначают открытым голосованием Правительства"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_4172/3e4facc6a5bea986adfaea21324b9fb33929f428/','ФКЗ требует индивидуального тайного голосования.',true),
('Конституционный Суд РФ','При назначении судьи КС РФ за кандидатуру проголосовало большинство присутствующих, но меньше половины общего числа сенаторов. Назначен ли кандидат?','["Да, достаточно большинства присутствующих","Да, если за него проголосовал председатель палаты","Нет, требуется не менее двух третей от общего числа сенаторов","Нет, требуется большинство от общего числа сенаторов"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_4172/3e4facc6a5bea986adfaea21324b9fb33929f428/','Требуется большинство от общего числа сенаторов, а не только присутствующих.',true),
('Конституционный Суд РФ','После выбытия судьи КС РФ состав уменьшился до семи. Когда Президент должен представить новую кандидатуру в Совет Федерации?','["Не позднее 14 дней после открытия вакансии","Не позднее трёх месяцев после открытия вакансии","Не позднее месяца со дня открытия вакансии","Не позднее шести месяцев после открытия вакансии"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_4172/3e4facc6a5bea986adfaea21324b9fb33929f428/','При составе менее восьми судей действует месячный срок для внесения представления.',true),
('Конституционный Суд РФ','Судьи Конституционного Суда предложили принять решение по итогам закрытого анонимного голосования. Какая процедура установлена ФКЗ?','["Тайное голосование бюллетенями","Открытое голосование путём поимённого опроса судей","Открытое голосование только поднятием рук без фиксации имён","Заочное голосование без установления позиции каждого судьи"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 72','https://www.consultant.ru/document/cons_doc_LAW_4172/755b3265e01a62b2c4571ac4cc1a791d5255a530/','Общее правило — открытое поимённое голосование.',true),
('Конституционный Суд РФ','В совещании при принятии решения Конституционного Суда председательствующий проголосовал первым. Как должно происходить голосование по закону?','["Председательствующий во всех случаях голосует последним","Председательствующий голосует первым","Председательствующий вообще не участвует в голосовании","Порядок каждый раз определяет представитель заявителя"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 72','https://www.consultant.ru/document/cons_doc_LAW_4172/755b3265e01a62b2c4571ac4cc1a791d5255a530/','Председательствующий голосует последним.',true),
('Конституционный Суд РФ','Конституционный Суд рассматривает вопрос о толковании Конституции РФ. Какое большинство требуется?','["Простое большинство судей, присутствующих на заседании","Не менее трёх четвертей от общего состава по закону","Единогласие всех судей","Не менее двух третей от числа действующих судей"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 72','https://www.consultant.ru/document/cons_doc_LAW_4172/755b3265e01a62b2c4571ac4cc1a791d5255a530/','Толкование Конституции требует не менее двух третей действующих судей.',true),
('Конституционный Суд РФ','Судья Конституционного Суда предложил воздержаться при голосовании по делу. Каково правило ФКЗ?','["Воздержание допускается при согласии Председателя","Воздержание допускается в спорах о компетенции","Судья не вправе воздержаться или уклониться от голосования","Воздержание допускается только по вопросам толкования"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 72','https://www.consultant.ru/document/cons_doc_LAW_4172/755b3265e01a62b2c4571ac4cc1a791d5255a530/','Воздерживаться при принятии решения запрещено.',true),
('Конституционный Суд РФ','При обычном голосовании по делу Конституционного Суда, не подпадающему под специальное правило, какое большинство требуется?','["Большинство от общего числа сенаторов","Большинство участвовавших в голосовании судей","Не менее трёх четвертей действующих судей","Единогласие всех назначенных судей"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 72','https://www.consultant.ru/document/cons_doc_LAW_4172/755b3265e01a62b2c4571ac4cc1a791d5255a530/','Общее правило требует большинства участвовавших в голосовании судей.',true),
('Конституционный Суд РФ','Участник дела хочет подать апелляционную жалобу на итоговое решение Конституционного Суда. Какова юридическая оценка?','["Решение окончательно и не подлежит обжалованию","Апелляция возможна в Верховный Суд в течение месяца","Апелляция возможна в Совет Федерации","Обжалование допускается только в Правительство РФ"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 79','https://www.consultant.ru/document/cons_doc_LAW_4172/2c98ffa82f9ebf55b6903952db15f773d11403ee/','Решения Конституционного Суда окончательны и необжалуемы.',true),
('Конституционный Суд РФ','Законодатель предложил не исполнять решение Конституционного Суда до его подтверждения Государственной Думой. Соответствует ли это ФКЗ?','["Да, каждое решение требует утверждения обеими палатами","Да, решения КС РФ вступают в силу лишь после указа Президента","Нет, требуется подтверждение только Верховным Судом","Нет, решение действует непосредственно и не требует подтверждения"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 79','https://www.consultant.ru/document/cons_doc_LAW_4172/2c98ffa82f9ebf55b6903952db15f773d11403ee/','Решение не зависит от подтверждения другими органами.',true),
('Конституционный Суд РФ','После признания нормативного акта неконституционным законодатель принял точно такой же акт, рассчитывая преодолеть решение Суда. Допустимо ли это?','["Да, позднейший акт всегда устраняет постановление Суда","Да, если повторное голосование было единогласным","Нет, повторное принятие того же акта не преодолевает юридическую силу постановления","Да, если новый акт имеет тот же номер и дату"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 79','https://www.consultant.ru/document/cons_doc_LAW_4172/2c98ffa82f9ebf55b6903952db15f773d11403ee/','Юридическая сила постановления КС РФ не преодолевается повторным принятием того же акта.',true),
('Конституционный Суд РФ','Когда вступает в силу итоговое решение Конституционного Суда по делу, рассмотренному на заседании с проведением слушания?','["По истечении 14 дней после провозглашения","Немедленно после провозглашения","Только после регистрации в Министерстве юстиции","С момента утверждения Советом Федерации"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 79','https://www.consultant.ru/document/cons_doc_LAW_4172/2c98ffa82f9ebf55b6903952db15f773d11403ee/','Итоговое решение после слушания вступает в силу немедленно после провозглашения.',true),
('Конституционный Суд РФ','Для постановления Конституционного Суда, принятого без проведения слушания по статье 47.1, какой момент вступления в силу установлен законом?','["Со дня опубликования в установленном порядке","Немедленно после закрытого обсуждения, до опубликования","Через месяц после опубликования","После отдельного голосования Федерального Собрания"]'::jsonb,0,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 79','https://www.consultant.ru/document/cons_doc_LAW_4172/2c98ffa82f9ebf55b6903952db15f773d11403ee/','Постановление без слушания вступает в силу со дня публикации.',true),
('Конституционный Суд РФ','Муниципальное образование, чьи права затронуты применённым в деле нормативным актом, намерено подать жалобу в Конституционный Суд через орган МСУ. Допускается ли это?','["Нет, жаловаться могут только физические лица","Нет, муниципалитет должен обращаться только через губернатора","Да, но только после принятия федерального закона о конкретном обращении","Да, муниципалитет через органы местного самоуправления обладает таким правом"]'::jsonb,3,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 96','https://www.consultant.ru/document/cons_doc_LAW_4172/c595c4bcfef00c500112b510fd4e75c509b07884/','Статья 96 прямо упоминает муниципальные образования в лице органов местного самоуправления.',true),
('Конституционный Суд РФ','Гражданин исчерпал внутригосударственные средства судебной защиты и собирается оспорить применённую норму в КС РФ. Каков общий срок подачи жалобы?','["Не позднее 14 дней после судебного решения","Не позднее трёх лет после соответствующего судебного решения","Не позднее одного года после соответствующего судебного решения","Без ограничения срока независимо от судебного решения"]'::jsonb,2,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 97','https://www.consultant.ru/document/cons_doc_LAW_4172/c3a2029ff68a604b4daa4e423cee7798d5fc126a/','Общее правило допустимости предусматривает один год после решения об исчерпании средств защиты.',true),
('Конституционный Суд РФ','Заявитель намерен оспорить применённый в его деле закон в КС РФ, не исчерпав предусмотренные средства судебной защиты. Каков общий результат?','["Жалоба автоматически рассматривается по существу","Жалоба не удовлетворяет критерию допустимости","Пропуск средств защиты всегда компенсируется согласием заявителя","Жалоба обязательно превращается в законодательную инициативу"]'::jsonb,1,'ФКЗ от 21.07.1994 № 1-ФКЗ «О Конституционном Суде Российской Федерации»','статья 97','https://www.consultant.ru/document/cons_doc_LAW_4172/c3a2029ff68a604b4daa4e423cee7798d5fc126a/','Статья 97 требует исчерпания иных внутригосударственных средств судебной защиты.',true),
('Судебная система РФ','Законодатель предлагает передать рассмотрение уголовных дел с вынесением приговоров самостоятельной комиссии при министерстве. Почему это недопустимо?','["Правосудие осуществляется исключительно судами","Нужна только письменная санкция министра","Допустимо, если члены комиссии имеют юридическое образование","Допустимо после согласия регионального законодательного собрания"]'::jsonb,0,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_12834/4aa549c1313d7821cc666a32cbb84c43e294199d/','Судебную власть осуществляют только суды.',true),
('Судебная система РФ','Председатель исполнительного органа субъекта требует согласовывать судебные решения с администрацией. Какова конституционно-правовая оценка?','["Допускается для судов районного звена","Допускается при рассмотрении административных дел","Допускается только по делам с бюджетными последствиями","Судебная власть самостоятельна и независима от исполнительной"]'::jsonb,3,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_12834/4aa549c1313d7821cc666a32cbb84c43e294199d/','Судебная власть действует независимо от исполнительной и законодательной.',true),
('Судебная система РФ','Какой перечень форм осуществления судебной власти закрепляет ФКЗ «О судебной системе»?','["Только гражданское и уголовное судопроизводство","Законодательный надзор, бюджетный контроль и следствие","Конституционное, гражданское, административное и уголовное судопроизводство","Конституционное, муниципальное и парламентское производство"]'::jsonb,2,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_12834/4aa549c1313d7821cc666a32cbb84c43e294199d/','Статья 1 прямо называет четыре вида судопроизводства.',true),
('Судебная система РФ','Регион разработал собственный порядок судопроизводства для мировых судей, противоречащий федеральным процессуальным законам. Какое правило о единстве судебной системы нарушено?','["Процессуальные правила определяет каждый мировой судья самостоятельно","Мировые судьи соблюдают установленные федеральными законами правила судопроизводства","Региональные правила всегда имеют приоритет над федеральными","Процессуальные правила утверждаются по соглашению с заявителями"]'::jsonb,1,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_12834/68e773d7dd403ad52ca17b683f6135fdfeb63e60/','Единство судебной системы включает общие правила судопроизводства.',true),
('Судебная система РФ','Какое положение обеспечивает единство судебной системы РФ независимо от уровня суда?','["Единые правила судопроизводства, обязательность судебных актов и единство статуса судей","Подчинение всех судей высшему должностному лицу региона","Обязательное назначение всех мировых судей Президентом","Одинаковая территориальная подсудность всех дел"]'::jsonb,0,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_12834/68e773d7dd403ad52ca17b683f6135fdfeb63e60/','Единство системы выражается в совокупности предусмотренных законом гарантий.',true),
('Судебная система РФ','Для обеспечения единства судебной системы депутат предложил финансировать федеральные суды только из местных бюджетов. Каков действующий принцип?','["Финансирование федеральных судов из местного бюджета","Финансирование каждого суда из бюджета субъекта по усмотрению губернатора","Финансирование судов за счёт местных выборных комиссий","Финансирование федеральных судов и мировых судей из федерального бюджета"]'::jsonb,3,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_12834/68e773d7dd403ad52ca17b683f6135fdfeb63e60/','Статья 3 указывает финансирование федеральных судов и мировых судей из федерального бюджета.',true),
('Судебная система РФ','В чём заключается значение вступившего в силу судебного постановления для других регионов России?','["Обязательность сохраняется только в регионе вынесения","Обязательность зависит от согласия регионального парламента","Его обязательность признаётся на всей территории Российской Федерации","Постановление действует только для судебного округа, где вынесено"]'::jsonb,2,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 3','https://www.consultant.ru/document/cons_doc_LAW_12834/68e773d7dd403ad52ca17b683f6135fdfeb63e60/','Единая система предполагает общероссийскую обязательность судебных постановлений.',true),
('Судебная система РФ','Закон субъекта предлагает создать чрезвычайный суд для разрешения одного конкретного политического кризиса. Соответствует ли это ФКЗ?','["Да, если кризис признан чрезвычайным губернатором","Нет, создание чрезвычайных судов не допускается","Да, если создать суд на срок не более месяца","Да, если он будет подотчётен региональной думе"]'::jsonb,1,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_12834/f6358ad89be3beafe0ad17249d808f1edaf49ded/','ФКЗ запрещает чрезвычайные суды.',true),
('Судебная система РФ','К какой категории судей в единой судебной системе относятся мировые судьи?','["Судьи общей юрисдикции субъектов РФ","Судьи специализированных федеральных арбитражных судов","Судьи Конституционного Суда РФ","Судьи федеральных военных судов"]'::jsonb,0,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_12834/f6358ad89be3beafe0ad17249d808f1edaf49ded/','Мировые судьи являются судьями общей юрисдикции субъектов.',true),
('Судебная система РФ','Является ли Верховный Суд Российской Федерации федеральным судом по статье 4 ФКЗ?','["Нет, Верховный Суд является судом субъекта РФ","Нет, Верховный Суд представляет отдельную несудебную ветвь власти","Да, но только в составе арбитражных судов округа","Да, Верховный Суд относится к федеральным судам"]'::jsonb,3,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_12834/f6358ad89be3beafe0ad17249d808f1edaf49ded/','Верховный Суд РФ прямо назван федеральным судом.',true),
('Судебная система РФ','Арбитражный суд субъекта РФ назван в проекте закона судом субъекта, не входящим в федеральную судебную систему. Каков правильный статус?','["Суд общей юрисдикции субъекта РФ","Муниципальный суд","Федеральный арбитражный суд","Третейский суд, не входящий в судебную систему"]'::jsonb,2,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_12834/f6358ad89be3beafe0ad17249d808f1edaf49ded/','Арбитражные суды субъектов входят в федеральные арбитражные суды.',true),
('Судебная система РФ','К какой системе судов закон относит военные суды?','["К мировым судьям субъектов","К федеральным судам общей юрисдикции","К муниципальным судам","К специализированным арбитражным судам"]'::jsonb,1,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_12834/f6358ad89be3beafe0ad17249d808f1edaf49ded/','Военные суды названы в системе федеральных судов общей юрисдикции.',true),
('Судебная система РФ','Суд установил противоречие между применимым актом должностного лица и федеральным законом. Как должен разрешаться спор о применимом праве?','["В соответствии с нормой, имеющей большую юридическую силу","На основании более позднего письма должностного лица","С применением акта регионального ведомства вне зависимости от иерархии","По усмотрению участника, первым обратившегося в суд"]'::jsonb,0,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_12834/6c93431d88d53ddf0e85cfa6f872ff1af1cd2dc8/','Суд применяет положение большей юридической силы.',true),
('Судебная система РФ','Законопроект предполагает отменить независимость судей ради ускорения исполнения решений органов власти. Допускает ли это ФКЗ?','["Да, если ускорится судопроизводство","Да, если закон будет принят большинством депутатов","Да, если мера распространится только на районные суды","Нет, НПА не могут отменять или умалять независимость судей"]'::jsonb,3,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_12834/6c93431d88d53ddf0e85cfa6f872ff1af1cd2dc8/','Независимость судей не может быть умалена нормативными актами.',true),
('Судебная система РФ','На судью оказывается незаконное давление при рассмотрении дела. Какая реакция предусмотрена законом?','["Давление допускается в административных делах","Применяются лишь внутренние меры профсоюза","Виновные несут установленную федеральным законом ответственность","Вопрос решается исключительно устной беседой сторон"]'::jsonb,2,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_12834/6c93431d88d53ddf0e85cfa6f872ff1af1cd2dc8/','Незаконное влияние на судей влечёт юридическую ответственность.',true),
('Судебная система РФ','Исполнительный орган другого субъекта РФ отказывается выполнять вступившее в силу судебное постановление, ссылаясь на территориальность суда. Какова оценка?','["Оно обязательно только в субъекте, где вынесено","Постановление обязательно к исполнению на всей территории России","Оно обязательно только для федеральных органов","Его исполнение зависит от согласия другого субъекта"]'::jsonb,1,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_12834/d6b56497f4ddd603a73e5414256b82067058de03/','Судебные постановления обязательны на всей территории страны.',true),
('Судебная система РФ','Муниципальная организация игнорирует вступившее в силу судебное постановление. Предусматривает ли ФКЗ ответственность за неисполнение?','["Да, ответственность установлена федеральным законом","Нет, муниципальные организации освобождены","Да, но только за решения Верховного Суда","Нет, ответственность касается только физических лиц"]'::jsonb,0,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_12834/d6b56497f4ddd603a73e5414256b82067058de03/','Неисполнение судебного постановления влечёт ответственность.',true),
('Судебная система РФ','Как определяется обязательность решений иностранных судов и международных арбитражей в Российской Федерации по общему правилу?','["Исключительно законами субъектов РФ","Автоматически, независимо от договоров и компетенции органов","Уставом муниципального образования","Международными договорами Российской Федерации с учётом действующих ограничений"]'::jsonb,3,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 6','https://www.consultant.ru/document/cons_doc_LAW_12834/d6b56497f4ddd603a73e5414256b82067058de03/','Статья 6 устанавливает международно-договорную основу с предусмотренными исключениями.',true),
('Судебная система РФ','Региональный закон требует закрытого судебного рассмотрения любого имущественного спора без специального федерального основания. Какое правило нарушено?','["Закрытые заседания устанавливает закон субъекта по любому делу","Гласность относится только к уголовным делам","Судебные разбирательства открыты, закрытые допускаются в случаях федерального закона","Закрытый режим определяется исключительно желанием истца"]'::jsonb,2,'ФКЗ от 31.12.1996 № 1-ФКЗ «О судебной системе Российской Федерации»','статья 9','https://www.consultant.ru/document/cons_doc_LAW_12834/8999238b1f308b764f6923ca15c49e6ed73c5df9/','Принцип гласности допускает закрытое заседание лишь в предусмотренных федеральным законом случаях.',true),
('Правительство РФ: акты','Федеральное ведомство просит Правительство издать нормативные общеобязательные правила в форме распоряжения. Какая форма предусмотрена ФКЗ?','["Распоряжение Правительства","Постановление Правительства","Протокол рабочего совещания Правительства","Письмо Аппарата Правительства"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Нормативные акты Правительства издаются в форме постановлений.',true),
('Правительство РФ: акты','Правительство принимает оперативное ненормативное решение по текущему вопросу. Какая форма акта применяется?','["Распоряжение Правительства","Постановление нормативного характера","Федеральный конституционный закон","Указ Президента"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Оперативные ненормативные решения издаются распоряжениями.',true),
('Правительство РФ: акты','Кто подписывает постановления и распоряжения Правительства Российской Федерации?','["Председатель Государственной Думы","Председатель Совета Федерации","Генеральный прокурор Российской Федерации","Председатель Правительства Российской Федерации"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Акты Правительства подписываются его Председателем.',true),
('Правительство РФ: акты','Правительство намерено придать нормативному акту силу только в одном федеральном округе, не определяя особого порядка вступления в силу. Каково общее правило?','["Акты всегда вступают в силу отдельно по субъектам","Акты автоматически действуют только по месту подписания","Акты вступают в силу одновременно на всей территории России, если иной порядок не указан","Срок вступления зависит только от регионального опубликования"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','По умолчанию вступление в силу происходит одновременно на всей территории РФ.',true),
('Правительство РФ: акты','Постановление Правительства затрагивает права и обязанности граждан и предусматривает вступление в силу до официального опубликования. Как оценить положение?','["Допустимо для любого постановления Правительства","Недопустимо: не ранее дня официального опубликования","Допустимо только при согласовании с Государственной Думой","Допустимо, если акт подписан в конце года"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Акты, затрагивающие права и обязанности граждан, вступают в силу не ранее опубликования.',true),
('Правительство РФ: акты','Может ли акт Правительства быть предметом судебного обжалования?','["Да, ФКЗ прямо предусматривает судебное обжалование","Нет, правительственные акты не подлежат судебному контролю","Да, но только с разрешения Совета Федерации","Нет, оспариваются лишь акты региональных администраций"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Акты Правительства могут быть обжалованы в суд.',true),
('Правительство РФ: акты','Акт Правительства противоречит указу Президента РФ. Кто вправе отменить его по ФКЗ?','["Председатель Госдумы единолично","Глава субъекта РФ","Совет Федерации без участия Президента","Президент Российской Федерации"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','Президент может отменить противоречащие акты Правительства.',true),
('Правительство РФ: акты','Может ли Правительство издавать постановления на основании распоряжений и поручений Президента РФ?','["Нет, только Конституция и ФКЗ служат основанием","Да, но лишь после их утверждения Сенатом","Да, они входят в правовую основу издания актов Правительства","Нет, Правительство вправе ссылаться только на федеральные законы"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/4626e87bae831614969a531df561aac412e1d3be/','ФКЗ включает указы, распоряжения и поручения Президента в основания актов.',true),
('Полномочия Президента РФ','Кто утверждает структуру федеральных органов исполнительной власти по предложению Председателя Правительства РФ?','["Совет Федерации","Президент Российской Федерации","Государственная Дума","Государственный Совет"]'::jsonb,1,'Конституция Российской Федерации','статья 83','https://minjust.gov.ru/ru/documents/8011/','Статья 83 возлагает утверждение структуры на Президента.',true),
('Полномочия Президента РФ','Президент предлагает кандидатуру Председателя Правительства. Какая палата участвует в её утверждении по действующей Конституции?','["Государственная Дума","Совет Федерации","Обе палаты одним голосованием","Конституционный Суд"]'::jsonb,0,'Конституция Российской Федерации','статья 83','https://minjust.gov.ru/ru/documents/8011/','Государственная Дума утверждает кандидатуру, предложенную Президентом.',true),
('Полномочия Президента РФ','Какая должность непосредственно назначает выборы Государственной Думы?','["Председатель Правительства","Председатель Совета Федерации","Председатель Центральной избирательной комиссии","Президент Российской Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 84','https://minjust.gov.ru/ru/documents/8011/','Президент назначает выборы Госдумы по конституционной процедуре.',true),
('Полномочия Президента РФ','Кто направляет ежегодные послания Федеральному Собранию о положении в стране и основных направлениях политики?','["Председатель Правительства","Председатель Конституционного Суда","Президент Российской Федерации","Председатель Центрального банка"]'::jsonb,2,'Конституция Российской Федерации','статья 84','https://minjust.gov.ru/ru/documents/8011/','Ежегодное послание Федеральному Собранию — полномочие Президента.',true),
('Полномочия Президента РФ','Между двумя субъектами РФ возник конфликт полномочий органов государственной власти. Какую процедуру вправе использовать Президент?','["Упразднение обоих органов без судебной процедуры","Согласительные процедуры с возможной последующей передачей спора суду","Обязательное проведение всероссийского референдума по каждому спору","Передачу любого спора исключительно Центральной избирательной комиссии"]'::jsonb,1,'Конституция Российской Федерации','статья 85','https://minjust.gov.ru/ru/documents/8011/','Президент может применять согласительные процедуры, затем передавать спор соответствующему суду.',true),
('Полномочия Президента РФ','Кто является Верховным Главнокомандующим Вооружёнными Силами РФ?','["Президент Российской Федерации","Председатель Правительства","Председатель Совета Федерации","Министр обороны как самостоятельный глава государства"]'::jsonb,0,'Конституция Российской Федерации','статья 87','https://minjust.gov.ru/ru/documents/8011/','Президент занимает конституционный статус Верховного Главнокомандующего.',true),
('Полномочия Президента РФ','Какие правовые акты издаёт Президент Российской Федерации?','["Постановления и распоряжения Правительства","Федеральные законы и определения суда","Приказы министерств и постановления Госдумы","Указы и распоряжения"]'::jsonb,3,'Конституция Российской Федерации','статья 90','https://minjust.gov.ru/ru/documents/8011/','Конституция предусматривает президентские указы и распоряжения.',true),
('Полномочия Президента РФ','Допустимо ли указом Президента устанавливать правило, противоречащее федеральному закону?','["Да, президентские указы всегда выше федеральных законов","Да, если акт принят в конце срока полномочий","Нет, указ и распоряжение Президента не должны противоречить федеральным законам","Да, если распоряжение издано в электронной форме"]'::jsonb,2,'Конституция Российской Федерации','статья 90','https://minjust.gov.ru/ru/documents/8011/','Конституция запрещает противоречие президентских актов федеральным законам.',true),
('Полномочия Президента РФ','Какую гарантию Конституция закрепляет для действующего Президента Российской Федерации?','["Право единолично отменять федеральные законы","Неприкосновенность","Право произвольно менять срок полномочий","Освобождение от действия Конституции"]'::jsonb,1,'Конституция Российской Федерации','статья 91','https://minjust.gov.ru/ru/documents/8011/','Действующий Президент обладает неприкосновенностью.',true),
('Полномочия Президента РФ','Председатель Правительства временно исполняет обязанности Президента. Какое полномочие для него прямо ограничено Конституцией?','["Назначение референдума Российской Федерации","Выполнение всех текущих функций по руководству исполнительной властью","Обеспечение представительства государства в обычных отношениях","Издание правовых актов в допустимых пределах полномочий"]'::jsonb,0,'Конституция Российской Федерации','статья 92','https://www.consultant.ru/document/cons_doc_LAW_28399/23d4df0aa402b2458f36c9aa0022a4894c7116a3/','Исполняющий обязанности Президента не может назначать референдум.',true)
